{"content":"import copy
import json


class RestAPI:
    def __init__(self, database=None):
        self.database = copy.deepcopy(database) if database is not None else {"users": []}

    def get(self, url, payload=None):
        if url != "/users":
            raise ValueError("Unknown GET endpoint: " + url)

        names = None if payload is None else json.loads(payload)["users"]
        users = self.database["users"]
        if names is not None:
            users = [user for user in users if user["name"] in names]
        return json.dumps({"users": sorted(users, key=lambda user: user["name"])})

    def post(self, url, payload=None):
        if url not in ("/add", "/iou"):
            raise ValueError("Unknown POST endpoint: " + url)
        if payload is None:
            raise ValueError("A POST payload is required")
        data = json.loads(payload)
        users = {user["name"]: user for user in self.database["users"]}

        if url == "/add":
            name = data["user"]
            if name in users:
                raise ValueError("User already exists: " + name)
            user = {"name": name, "owes": {}, "owed_by": {}, "balance": 0.0}
            self.database["users"].append(user)
            return json.dumps(user)

        lender_name = data["lender"]
        borrower_name = data["borrower"]
        if lender_name == borrower_name:
            raise ValueError("Lender and borrower must be different users")
        lender = users[lender_name]
        borrower = users[borrower_name]
        amount = data["amount"]

        # Opposing loans cancel rather than creating debts in both directions.
        debt = (
            borrower["owes"].get(lender_name, 0.0)
            - borrower["owed_by"].get(lender_name, 0.0)
            + amount
        )
        for user, other_name in ((lender, borrower_name), (borrower, lender_name)):
            user["owes"].pop(other_name, None)
            user["owed_by"].pop(other_name, None)

        if debt > 0:
            borrower["owes"][lender_name] = debt
            lender["owed_by"][borrower_name] = debt
        elif debt < 0:
            lender["owes"][borrower_name] = -debt
            borrower["owed_by"][lender_name] = -debt

        for user in (lender, borrower):
            user["balance"] = sum(user["owed_by"].values()) - sum(user["owes"].values())
        return self.get("/users", json.dumps({"users": [lender_name, borrower_name]}))
