{"content":"import json
import unittest

from rest_api import RestAPI


def user(name, owes=None, owed_by=None):
    owes = owes or {}
    owed_by = owed_by or {}
    return {
        "name": name,
        "owes": owes,
        "owed_by": owed_by,
        "balance": sum(owed_by.values()) - sum(owes.values()),
    }


class RestAPITest(unittest.TestCase):
    def loan(self, api, lender, borrower, amount):
        return json.loads(api.post("/iou", json.dumps({
            "lender": lender, "borrower": borrower, "amount": amount,
        })))

    def test_empty_database(self):
        self.assertEqual(json.loads(RestAPI().get("/users")), {"users": []})

    def test_add_and_persist_user(self):
        api = RestAPI()
        self.assertEqual(json.loads(api.post("/add", '{"user":"Adam"}')), user("Adam"))
        self.assertEqual(json.loads(api.get("/users")), {"users": [user("Adam")]})

    def test_sorted_and_filtered_users(self):
        api = RestAPI({"users": [user("Dan"), user("Bob"), user("Adam")]})
        self.assertEqual(json.loads(api.get("/users")), {
            "users": [user("Adam"), user("Bob"), user("Dan")],
        })
        self.assertEqual(json.loads(api.get("/users", '{"users":["Dan","Adam"]}')), {
            "users": [user("Adam"), user("Dan")],
        })
        self.assertEqual(json.loads(api.get("/users", '{"users":[]}')), {"users": []})

    def test_new_and_repeated_loan(self):
        api = RestAPI({"users": [user("Bob"), user("Adam")]})
        for total in (5.25, 10.5):
            response = self.loan(api, "Bob", "Adam", 5.25)
            expected = {"users": [
                user("Adam", owes={"Bob": total}),
                user("Bob", owed_by={"Adam": total}),
            ]}
            self.assertEqual(response, expected)
            self.assertEqual(json.loads(api.get("/users")), expected)

    def test_reverse_loan_reduces_cancels_or_reverses_debt(self):
        for amount, expected in (
            (3, [user("Adam", owed_by={"Bob": 7}), user("Bob", owes={"Adam": 7})]),
            (10, [user("Adam"), user("Bob")]),
            (12.5, [user("Adam", owes={"Bob": 2.5}), user("Bob", owed_by={"Adam": 2.5})]),
        ):
            with self.subTest(amount=amount):
                api = RestAPI({"users": [
                    user("Adam", owed_by={"Bob": 10}), user("Bob", owes={"Adam": 10}),
                ]})
                self.assertEqual(self.loan(api, "Bob", "Adam", amount), {"users": expected})
                self.assertEqual(json.loads(api.get("/users")), {"users": expected})

    def test_other_debts_are_preserved_and_balances_recomputed(self):
        api = RestAPI({"users": [
            user("Adam", owes={"Chuck": 4}, owed_by={"Bob": 10}),
            user("Bob", owes={"Adam": 10}),
            user("Chuck", owed_by={"Adam": 4}),
        ]})
        self.assertEqual(self.loan(api, "Bob", "Adam", 12), {"users": [
            user("Adam", owes={"Chuck": 4, "Bob": 2}),
            user("Bob", owed_by={"Adam": 2}),
        ]})
        self.assertEqual(json.loads(api.get("/users", '{"users":["Chuck"]}')), {
            "users": [user("Chuck", owed_by={"Adam": 4})],
        })

    def test_database_is_not_shared_or_mutated(self):
        database = {"users": [user("Adam"), user("Bob")]}
        api = RestAPI(database)
        self.loan(api, "Adam", "Bob", 5)
        self.assertEqual(database, {"users": [user("Adam"), user("Bob")]})
        self.assertEqual(json.loads(RestAPI().get("/users")), {"users": []})

    def test_duplicate_user_does_not_change_database(self):
        api = RestAPI({"users": [user("Adam")]})
        with self.assertRaises(ValueError):
            api.post("/add", '{"user":"Adam"}')
        self.assertEqual(json.loads(api.get("/users")), {"users": [user("Adam")]})


if __name__ == "__main__":
    unittest.main()
